import{_ as i,l as o,o as e,c as h,v as r,p as s,x as t,d as S,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Strehl 比","description":"","frontmatter":{"title":"Strehl 比","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/strehl-ratio.md","filePath":"litho/strehl-ratio.md","lastUpdated":1789023840000}'),d={name:"litho/strehl-ratio.md"};function m(c,a,E,_,f,B){const l=o("Mermaid");return e(),h("div",null,[a[1]||(a[1]=r('<h1 id="strehl-比" tabindex="-1">Strehl 比 <a class="header-anchor" href="#strehl-比" aria-label="Permalink to &quot;Strehl 比&quot;">​</a></h1><div class="epigraph"><p>单项像差已经能把核拉歪、劈焦、搬家；还需要一个标量，问整块光瞳离「无像差圆孔」还有多远——Strehl 比把峰值强度收成衍射极限判据。</p><footer>—— Strehl 定义与 Maréchal 近似见 Born &amp; Wolf, Principles of Optics</footer></div><p><a href="/litho/distortion-field">上一课</a>把不糊的场相关平移写成畸变。缺口是：<strong>对比与套刻拆完之后，仍缺一条「系统还能不能叫衍射极限」的总判据</strong>。Strehl 不替代 NILS，也不替代套刻指纹。有限带宽如何把单色系数搅在一起，留给<a href="/litho/chromatic-bandwidth">色差与光源带宽</a>。不要从瑞利 CD 起笔，也不要引用未公开的镜头 Strehl 验收数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>球差、彗差、像散各自改核的形状；畸变甚至几乎不改峰值。车间要一句话回答：这块波前的 RMS 是否还小到可以当理想光瞳。Strehl 比</p> \\[S=\\frac{I_\\mathrm{peak}}{I_\\mathrm{Airy}} \\]<p>是有像差点扩散中心（或配平后的峰值）相对同一孔径无像差艾里峰值的强度比。\\(S\\to 1\\) 表示能量仍集中在主瓣。缺口因此是这条<strong>无量纲总指标</strong>，而不是再增加一个 Seidel 项。</p><p>Maréchal 把小像差下的 \\(S\\) 连到波前 RMS：相位误差不大时，\\(S\\approx\\exp\\bigl[-(2\\pi\\sigma)^2\\bigr]\\approx 1-(2\\pi\\sigma)^2\\)，其中 \\(\\sigma\\) 是光瞳上 \\(W\\) 的均方根（以波长为单位）。传统「衍射极限」口令 \\(S\\gtrsim 0.8\\) 大约对应 \\(\\sigma\\lesssim\\lambda/14\\)。这是显微镜 / 镜头车间的判据，不是光刻的 \\(k_1\\)。</p><h3 id="strehl-看不见的东西" tabindex="-1">Strehl 看不见的东西 <a class="header-anchor" href="#strehl-看不见的东西" aria-label="Permalink to &quot;Strehl 看不见的东西&quot;">​</a></h3><p>畸变主要搬家，峰值可以仍高，\\(S\\) 很好，套刻很差。切趾压低边缘透过率，即使 \\(W=0\\)，\\(S\\) 相对硬切艾里的定义也要声明参考光瞳。部分相干下晶圆上没有单一「峰值点扩散」，Strehl 仍是投影通道的镜头指标，不是空中像 NILS。</p><p><span class="marginnote">参考必须写清：相对无像差、同孔径、同切趾的峰值，还是相对理想 circ。换参考，\\(S\\) 换数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>干涉仪拟合出 \\(W\\)（Zernike 截断 + 残差），算 RMS \\(\\sigma\\)，再用 Maréchal 估 \\(S\\)，或直接对复光瞳做傅里叶变换读峰值。Malacara 的车间测试给出 \\(W\\)；Born &amp; Wolf 给出 \\(S\\) 与 \\(\\sigma\\) 的关系。大像差时指数近似崩溃，必须积分点扩散，不能靠 \\(\\lambda/14\\) 口令。</p><p>光刻用途：镜头出厂与加热补偿用 \\(S\\) 或 \\(\\sigma\\) 当健康度；层是否可印仍看该图形的 NILS 与套刻。密图形走光瞳边缘，对高阶径向项比 RMS 更苛刻——\\(S\\) 合格可以 NILS 不合格。</p><h3 id="与-mtf、nils-的分工" tabindex="-1">与 MTF、NILS 的分工 <a class="header-anchor" href="#与-mtf、nils-的分工" aria-label="Permalink to &quot;与 MTF、NILS 的分工&quot;">​</a></h3><p>MTF 是频率轴；NILS 是阈值边；Strehl 是点物峰值。三者相关：\\(\\sigma\\) 大则高频 MTF 掉、峰值掉。不可互换：对比反转时 MTF 变号，Strehl 仍可能是一个中等正数。工艺窗口用 NILS\\((z)\\)，不用 \\(S(z)\\) 冒充。</p><p><span class="marginnote">矢量成像里「艾里峰值」本身依赖偏振与薄膜。报 \\(S\\) 要声明标量还是指定偏振通道；不要把 TE 的 \\(S\\) 借给 TM 密线。</span></p>',17)),(e(),s(p,null,{default:t(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%85%89%E7%9E%B3%E6%B3%A2%E5%89%8D%20W%22%5D%20--%3E%20RMS%5B%22RMS%20%CF%83%22%5D%0A%20%20RMS%20--%3E%20MAR%5B%22Mar%C3%A9chal%EF%BC%9AS%20%E2%89%88%201-(2%CF%80%CF%83)%C2%B2%22%5D%0A%20%20W%20--%3E%20PSF%5B%22%E7%82%B9%E6%89%A9%E6%95%A3%E5%B3%B0%E5%80%BC%22%5D%0A%20%20PSF%20--%3E%20S%5B%22Strehl%20S%22%5D%0A%20%20S%20--%3E%20DL%5B%22%E8%A1%8D%E5%B0%84%E6%9E%81%E9%99%90%E5%8F%A3%E4%BB%A4%22%5D%0A%20%20DL%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B8%A6%E5%AE%BD%E6%90%85%E4%B9%B1%E5%8D%95%E8%89%B2%20W%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[S(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无像差时，光瞳上各面元在几何焦点同相叠加，峰值最高。残差相位让一部分面元失配，峰值能量被打进旁瓣与环，\\(S\\) 下降。Maréchal 把小相位的二阶展开收成 \\(\\sigma^2\\)，所以低阶与高阶只要 RMS 相同，近似给出同一 \\(S\\)——这正是它的边界：光刻密图形并不对所有空间频率一视同仁，边缘加权的高阶项更伤 NILS。</p><p>活塞不进 \\(\\sigma\\) 的有意义部分；整体倾斜只搬家（远心 / 畸变），适当扣除后才谈 Strehl。配平（加 \\(Z_4\\) 抵球差）是为了提高 \\(S\\) 或压 RMS，与焦深课选窗口中心是同一类操作。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到镜头是否接近衍射极限，用 \\(S\\) 或 \\(W_\\mathrm{RMS}\\)，并声明参考光瞳与 Zernike 截断。说到可印，用 NILS / 套刻。下一课把单色 \\(W\\) 变成 \\(\\lambda\\) 的函数，\\(S\\) 必须对光谱加权，不能只用中心波长的 Maréchal。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Strehl 不含杂散光、不含胶扩散。禁止把某代投影物镜的 Strehl 写成未公开验收值；Born &amp; Wolf 与 Maréchal 的公式已经够用。High-NA 变形光瞳的「理想峰值」要另定义参考。畸变已在上一课拆走：谈 \\(S\\) 时默认已扣除纯平移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Strehl 是有像差峰值相对理想艾里峰值的比；小像差下 Maréchal 连到 \\(W_\\mathrm{RMS}\\)。</li><li>\\(S\\gtrsim 0.8\\) 是车间衍射极限口令，不是产线 \\(k_1\\)。</li><li>看不见畸变套刻，也不替代 NILS。</li><li>参考光瞳、截断阶数、标量 / 矢量必须声明。</li><li>单色 \\(S\\) 下一课要对带宽积分。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Maréchal 衍射极限判据。</li></ul>',9))])}const A=i(d,[["render",m]]);export{u as __pageData,A as default};
